import React, { useCallback, useEffect, useState } from 'react';
import {
  Box,
  Paper,
  Typography,
  Button,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  CircularProgress,
  Alert,
  Grid,
  Card,
  CardContent,
  Chip,
  Tabs,
  Tab,
  LinearProgress,
  Tooltip
} from '@mui/material';
import ScrollableTableContainer from './shared/ScrollableTableContainer';
import { scrollableTabsSx } from '../constants/appShellLayout';
import PlayArrowIcon from '@mui/icons-material/PlayArrow';
import RefreshIcon from '@mui/icons-material/Refresh';
import ReplayIcon from '@mui/icons-material/Replay';
import SaveIcon from '@mui/icons-material/Save';
import TrendingDownIcon from '@mui/icons-material/TrendingDown';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import documentService, {
  OcrAutomationReport,
  OcrBenchmarkSummary,
  OcrFailedInvoice,
  OcrRegressionReport
} from '../services/documentService';

const pct = (v: number | null | undefined) =>
  v != null && !Number.isNaN(v) ? `${Math.round(v * 100)}%` : '—';

const AutomatedTestingDashboard: React.FC = () => {
  const [tab, setTab] = useState(0);
  const [reports, setReports] = useState<OcrAutomationReport[]>([]);
  const [latest, setLatest] = useState<OcrBenchmarkSummary | null>(null);
  const [results, setResults] = useState<Record<string, unknown>[]>([]);
  const [failed, setFailed] = useState<OcrFailedInvoice[]>([]);
  const [fieldCounts, setFieldCounts] = useState<Record<string, number>>({});
  const [regression, setRegression] = useState<OcrRegressionReport | null>(null);
  const [loading, setLoading] = useState(false);
  const [running, setRunning] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [listRes, latestRes, failedRes, regRes] = await Promise.all([
        documentService.getOcrAutomationReports().catch(() => ({ success: false, reports: [] })),
        documentService.getLatestOcrAutomation().catch(() => null),
        documentService.getOcrFailedInvoices().catch(() => null),
        documentService.getOcrRegression().catch(() => null)
      ]);
      if (listRes.success) setReports(listRes.reports);
      if (latestRes?.success) {
        setLatest(latestRes.report);
        setResults((latestRes.results as Record<string, unknown>[]) || []);
      }
      if (failedRes?.success) {
        setFailed(failedRes.failedInvoices || []);
        setFieldCounts(failedRes.fieldFailureCounts || {});
      }
      if (regRes?.success) setRegression(regRes.regression);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to load automation data');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const runAutomation = async (writeBaseline = false) => {
    setRunning(true);
    setError(null);
    try {
      await documentService.runOcrAutomation({ writeBaseline, workers: 2 });
      await load();
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Automation run failed');
    } finally {
      setRunning(false);
    }
  };

  const rerunFailed = async () => {
    setRunning(true);
    setError(null);
    try {
      await documentService.rerunFailedOcrTests();
      await load();
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Rerun failed');
    } finally {
      setRunning(false);
    }
  };

  const fieldAccuracy = latest?.field_accuracy || {};
  const passRate = latest?.pass_rate;

  return (
    <Box sx={{ mb: 4 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2, flexWrap: 'wrap', gap: 1 }}>
        <Typography variant="h6">Automated OCR + Invoice Testing</Typography>
        <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
          <Button startIcon={<RefreshIcon />} onClick={load} disabled={loading || running} size="small">
            Refresh
          </Button>
          <Tooltip title="Save current run as regression baseline">
            <Button
              startIcon={<SaveIcon />}
              onClick={() => runAutomation(true)}
              disabled={running}
              size="small"
              variant="outlined"
            >
              Set baseline
            </Button>
          </Tooltip>
          <Button
            startIcon={<ReplayIcon />}
            onClick={rerunFailed}
            disabled={running || failed.length === 0}
            size="small"
            variant="outlined"
          >
            Rerun failed
          </Button>
          <Button
            variant="contained"
            startIcon={running ? <CircularProgress size={18} color="inherit" /> : <PlayArrowIcon />}
            onClick={() => runAutomation(false)}
            disabled={running}
            size="small"
          >
            Run all tests
          </Button>
        </Box>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {regression?.has_baseline && (
        <Alert
          severity={regression.degraded ? 'warning' : 'success'}
          sx={{ mb: 2 }}
          icon={regression.degraded ? <TrendingDownIcon /> : <TrendingUpIcon />}
        >
          {regression.degraded
            ? `Regression detected — confidence Δ ${((regression.confidence_delta || 0) * 100).toFixed(1)}%`
            : `No significant regression — confidence Δ ${((regression.confidence_delta || 0) * 100).toFixed(1)}%`}
          {(regression.field_regressions?.length || 0) > 0 && (
            <Typography variant="caption" display="block">
              Regressed fields: {regression.field_regressions?.map((r) => r.field).join(', ')}
            </Typography>
          )}
        </Alert>
      )}

      {latest && (
        <Grid container spacing={2} sx={{ mb: 2 }}>
          {[
            { label: 'Cases run', value: latest.cases_run ?? '—' },
            { label: 'Pass rate', value: passRate != null ? pct(passRate) : '—' },
            { label: 'Mean confidence', value: pct(latest.mean_invoice_confidence) },
            { label: 'Avg time (ms)', value: latest.mean_processing_time_ms ?? latest.processing_time_summary?.mean_ms ?? '—' },
            { label: 'GST accuracy', value: pct(fieldAccuracy.gstin as number) },
            { label: 'Amount accuracy', value: pct(fieldAccuracy.amount as number) }
          ].map((card) => (
            <Grid item xs={6} md={2} key={card.label}>
              <Card variant="outlined">
                <CardContent sx={{ py: 1.5, '&:last-child': { pb: 1.5 } }}>
                  <Typography variant="caption" color="text.secondary">
                    {card.label}
                  </Typography>
                  <Typography variant="h6">{card.value}</Typography>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      )}

      <Tabs
        value={tab}
        onChange={(_, v) => setTab(v)}
        variant="scrollable"
        scrollButtons="auto"
        allowScrollButtonsMobile
        sx={{ mb: 2, ...scrollableTabsSx }}
      >
        <Tab label="Results" />
        <Tab label={`Failed (${failed.length})`} />
        <Tab label="Field failures" />
        <Tab label="History" />
      </Tabs>

      {tab === 0 && (
        <Paper variant="outlined">
          <ScrollableTableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Case ID</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Confidence</TableCell>
                <TableCell>Time (ms)</TableCell>
                <TableCell>Failed fields</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {results.length === 0 && (
                <TableRow>
                  <TableCell colSpan={5} align="center">
                    {loading ? 'Loading…' : 'No results — run automated tests.'}
                  </TableCell>
                </TableRow>
              )}
              {results.map((r) => {
                const passed = Boolean(r.passed);
                const conf = Number(r.invoice_confidence || 0);
                return (
                  <TableRow key={String(r.id)}>
                    <TableCell>{String(r.id)}</TableCell>
                    <TableCell>
                      <Chip
                        label={passed ? 'PASS' : 'FAIL'}
                        size="small"
                        color={passed ? 'success' : 'error'}
                      />
                    </TableCell>
                    <TableCell>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, minWidth: 120 }}>
                        <LinearProgress
                          variant="determinate"
                          value={conf * 100}
                          sx={{ flex: 1, height: 6, borderRadius: 1 }}
                          color={conf >= 0.7 ? 'success' : conf >= 0.5 ? 'warning' : 'error'}
                        />
                        <Typography variant="caption">{pct(conf)}</Typography>
                      </Box>
                    </TableCell>
                    <TableCell>{String(r.processing_time_ms ?? '—')}</TableCell>
                    <TableCell>
                      {((r.failed_fields as string[]) || []).map((f) => (
                        <Chip key={f} label={f} size="small" sx={{ mr: 0.5, mb: 0.5 }} />
                      ))}
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
          </ScrollableTableContainer>
        </Paper>
      )}

      {tab === 1 && (
        <Paper variant="outlined">
          <ScrollableTableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Invoice</TableCell>
                <TableCell>Reasons</TableCell>
                <TableCell>Failed fields</TableCell>
                <TableCell>Confidence</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {failed.length === 0 && (
                <TableRow>
                  <TableCell colSpan={4} align="center">
                    No failed invoices in latest run.
                  </TableCell>
                </TableRow>
              )}
              {failed.map((row) => (
                <TableRow key={row.id || row.file}>
                  <TableCell>{row.id || row.file}</TableCell>
                  <TableCell>
                    {(row.failure_reasons || [row.error]).filter(Boolean).map((reason) => (
                      <Chip key={reason} label={reason} size="small" sx={{ mr: 0.5 }} />
                    ))}
                  </TableCell>
                  <TableCell>{(row.failed_fields || []).join(', ') || '—'}</TableCell>
                  <TableCell>
                    {row.invoice_confidence != null ? pct(row.invoice_confidence) : '—'}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
          </ScrollableTableContainer>
        </Paper>
      )}

      {tab === 2 && (
        <Paper variant="outlined" sx={{ p: 2 }}>
          {Object.keys(fieldCounts).length === 0 ? (
            <Typography variant="body2" color="text.secondary">
              No field failure clusters.
            </Typography>
          ) : (
            Object.entries(fieldCounts).map(([field, count]) => (
              <Box key={field} sx={{ mb: 1.5 }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 0.5 }}>
                  <Typography variant="body2">{field}</Typography>
                  <Typography variant="caption">{count} failures</Typography>
                </Box>
                <LinearProgress
                  variant="determinate"
                  value={Math.min(100, count * 25)}
                  color="warning"
                />
              </Box>
            ))
          )}
        </Paper>
      )}

      {tab === 3 && (
        <Paper variant="outlined">
          <ScrollableTableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Report ID</TableCell>
                <TableCell>Created</TableCell>
                <TableCell>Pass rate</TableCell>
                <TableCell>Confidence</TableCell>
                <TableCell>Regression</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {reports.map((r) => (
                <TableRow key={r.id}>
                  <TableCell>{r.id}</TableCell>
                  <TableCell>{r.createdAt ? new Date(r.createdAt).toLocaleString() : '—'}</TableCell>
                  <TableCell>{r.passRate != null ? pct(r.passRate) : '—'}</TableCell>
                  <TableCell>{pct(r.meanInvoiceConfidence)}</TableCell>
                  <TableCell>
                    {r.regressionDegraded ? (
                      <Chip label="Degraded" size="small" color="warning" />
                    ) : (
                      <Chip label="OK" size="small" color="success" variant="outlined" />
                    )}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
          </ScrollableTableContainer>
        </Paper>
      )}
    </Box>
  );
};

export default AutomatedTestingDashboard;
